namespace CheckoutPricing.UnitTests;

public class GoldDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var checkout = typeof(CheckoutPricing.Application.ApplicationMarker).Assembly
            .GetTypes().FirstOrDefault(t => t.Name.Contains("Checkout", StringComparison.Ordinal));

        Assert.True(checkout is not null,
            "No checkout/pricing type exists in CheckoutPricing.Application, so a Gold 100.00 subtotal cannot yield 95.00.");
    }
}
